      +(d.link?('<a class="mlink" href="'+esc(d.link.href)+'">Forma parte de: '+esc(d.link.text)+' →</a>'):'')
      // 🔴 UN HUECO PARA QUIEN SEPA MÁS QUE ESTE MODAL. Esta ficha de insignia se usa en media web
